// ============================================================================
// testbench_replay.v
//
// Replays the EXACT clk/rst_n/enable/I stimulus timing captured in a reference
// waveform trace, against OUR OWN reconstructed netlist. This drives the
// signals -- it does not read, print, or interpret the trace's O/success
// values; the point is purely to see whether our replica's own O_0_..O_7_ /
// success behave the same way when given identical stimulus, as a
// correctness check on the extraction.
//
// Auto-generated from a VCD's value-change events -- clk/rst_n/enable/I only.
// 723 timed stimulus events, spanning 0 to 3120000 ps.
// ============================================================================

`timescale 1ps/1ps

module testbench_replay;

    reg  clk, rst_n, enable, I;
    wire O_0_, O_1_, O_2_, O_3_, O_4_, O_5_, O_6_, O_7_;
    wire [7:0] output_hex = {O_7_, O_6_, O_5_, O_4_, O_3_, O_2_, O_1_, O_0_};

    JaneStreet dut (
        .I       (I),
        .clk     (clk),
        .enable  (enable),
        .rst_n   (rst_n),
        .O_0_    (O_0_), .O_1_ (O_1_), .O_2_ (O_2_), .O_3_ (O_3_),
        .O_4_    (O_4_), .O_5_ (O_5_), .O_6_ (O_6_), .O_7_ (O_7_)
    );

    initial begin
        $dumpfile("replay.vcd");
        $dumpvars(0, testbench_replay);
    end

    // Per-cycle monitor, same style as the main testbench
    always @(posedge clk) begin
        $display("t=%0t  rst_n=%b enable=%b I=%b  ->  O=0x%02h",
                   $time, rst_n, enable, I, output_hex);
    end

